package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.dto.DentistRequest;import com.sunrise.dentalclinic.service.DentistService;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/dentists") public class DentistController{private final DentistService service;public DentistController(DentistService s){service=s;}@GetMapping String list(Model m){m.addAttribute("dentists",service.all());return "dentists/list";}@GetMapping("/new")String create(Model m){m.addAttribute("dentistRequest",new DentistRequest("",""));return "dentists/form";}@PostMapping String save(@Valid @ModelAttribute DentistRequest dentistRequest,BindingResult e,RedirectAttributes r){if(e.hasErrors())return "dentists/form";service.create(dentistRequest);r.addFlashAttribute("success","Dentist added");return "redirect:/dentists";}@GetMapping("/{id}/edit")String edit(@PathVariable Long id,Model m){var d=service.get(id);m.addAttribute("dentist",d);m.addAttribute("dentistRequest",new DentistRequest(d.getName(),d.getSpecialization()));return "dentists/form";}@PostMapping("/{id}")String update(@PathVariable Long id,@Valid @ModelAttribute DentistRequest dentistRequest,BindingResult e,Model m){if(e.hasErrors()){m.addAttribute("dentist",service.get(id));return "dentists/form";}service.update(id,dentistRequest);return "redirect:/dentists";}@PostMapping("/{id}/toggle")String toggle(@PathVariable Long id){service.toggle(id);return "redirect:/dentists";}}
